fn safe_get(
    slice: &[i32],
    index: usize,
) -> Option<i32> {
    if index < slice.len() {
        Some(unsafe {
            *slice.as_ptr().add(index)
        })
    } else {
        None
    }
}

fn main() {
    let nums = [10, 20, 30];
    println!("{:?}", safe_get(&nums, 1));
}

